def load() -> pd.DataFrame:
    import pandas as pd, glob
    paths = sorted(glob.glob('data/environment/input/water-body-testing-*.csv'))
    dfs = []
    for p in paths:
        df = pd.read_csv(p)
        df['__source_file'] = p
        dfs.append(pd.concat([df.head(2), df.tail(2)], ignore_index=True))
    return pd.concat(dfs, ignore_index=True)

def process(yearly_exceedance_rates):
    import pandas as pd
    out = yearly_exceedance_rates[yearly_exceedance_rates['higher_than_avg_2dp']].copy()
    return out[['Year']].sort_values('Year').reset_index(drop=True)
